def solve(n):
    N = 0
    # Use compositions of n into 5 parts: x1 + x2 + x3 + x4 + x5 = n
    # x1 >= 1, x2 >= 1, x3 >= 1, x4 >= 1, x5 >= 1
    # This is equivalent to y1 + y2 + y3 + y4 + y5 = n - 5, yi >= 0
    # We can iterate over y1, y2, y3, y4 and y5 will be determined.
    for x1 in range(1, n - 3):
        for x2 in range(1, n - x1 - 2):
            for x3 in range(1, n - x1 - x2 - 1):
                for x4 in range(1, n - x1 - x2 - x3):
                    x5 = n - (x1 + x2 + x3 + x4)
                    if count_acute_angles((x1, x2, x3, x4, x5), n) == 2:
                        N += 1
    return (n * N) // 5

